-- 1. row counts. Run before the insert (EXAMPLE_STOCK just created, empty) and after it.
-- After the insert, OURS must equal EXPECTED, and OTHERS must equal ROWS_NOW of the run before the insert.
SELECT 'STOCK_INFO' AS TABLE_NAME, (SELECT COUNT(*) FROM STOCK_INFO) AS ROWS_NOW, (SELECT COUNT(*) FROM STOCK_INFO WHERE STOCK_NO IN (SELECT STOCK_NO FROM EXAMPLE_STOCK)) AS OURS, (SELECT COUNT(*) FROM STOCK_INFO) - (SELECT COUNT(*) FROM STOCK_INFO WHERE STOCK_NO IN (SELECT STOCK_NO FROM EXAMPLE_STOCK)) AS OTHERS, 75 AS EXPECTED FROM DUAL
UNION ALL
SELECT 'SELL_DATE' AS TABLE_NAME, (SELECT COUNT(*) FROM SELL_DATE) AS ROWS_NOW, (SELECT COUNT(*) FROM SELL_DATE WHERE STOCK_NO IN (SELECT STOCK_NO FROM EXAMPLE_STOCK)) AS OURS, (SELECT COUNT(*) FROM SELL_DATE) - (SELECT COUNT(*) FROM SELL_DATE WHERE STOCK_NO IN (SELECT STOCK_NO FROM EXAMPLE_STOCK)) AS OTHERS, 75 AS EXPECTED FROM DUAL
UNION ALL
