SELECT 'BROKER_INFO' AS TABLE_NAME, (SELECT COUNT(*) FROM BROKER_INFO) AS ROWS_NOW, (SELECT COUNT(*) FROM BROKER_INFO WHERE MEMBER_NO IN (SELECT MEMBER_NO FROM MEMBER WHERE MEMBER_EMAIL = 'example-listings@example.invalid')) AS OURS, (SELECT COUNT(*) FROM BROKER_INFO) - (SELECT COUNT(*) FROM BROKER_INFO WHERE MEMBER_NO IN (SELECT MEMBER_NO FROM MEMBER WHERE MEMBER_EMAIL = 'example-listings@example.invalid')) AS OTHERS, 1 AS EXPECTED FROM DUAL
